/* 能源与环境经济学者库 — client-side rendering. Data: data.js (generated by scripts/build.py). */
(function () {
  "use strict";

  const CONFIG = {
    repoUrl: "https://github.com/environment-econ-faculty/environment-econ-faculty.github.io",
  };

  const D = window.EEE_DATA;
  const app = document.getElementById("app");
  if (!D) { app.innerHTML = `<p class="empty">data.js 未找到，请先运行 python scripts/build.py</p>`; return; }
  document.getElementById("generated").textContent = D.generated;
  document.getElementById("repo-link").href = CONFIG.repoUrl;

  // ---------------------------------------------------------------- lookups ----
  const SCHOOL = new Map(D.schools.map((s) => [s.name, s]));
  const SCHOLAR = new Map(D.scholars.map((s) => [s.id, s]));
  const RANKS = ["正教授", "副教授", "助理教授"];
  const TIERS = ["核心领域", "领域之一", "相关研究"];
  const APPTS = ["经济系", "合聘", "外系挂靠"];
  const TIER_HELP = {
    "核心领域": "能源/环境/资源经济学是其主要研究领域",
    "领域之一": "在院系页面或简历中将 EEE 列为研究领域之一",
    "相关研究": "未明确列为领域，但有较多 EEE 相关研究",
  };
  const ord = (arr, v) => { const i = arr.indexOf(v); return i < 0 ? 99 : i; };
  const schoolRank = (name) => (SCHOOL.get(name) || {}).rank ?? 999;
  const schoolZh = (name) => (SCHOOL.get(name) || {}).zh || "";
  const schoolShort = (name) => (SCHOOL.get(name) || {}).short || name;
  const editUrl = (id) => `${CONFIG.repoUrl}/edit/main/data/scholars/${encodeURIComponent(id)}.md`;
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const link = (url, text) => url ? `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)}</a>` : "";

  const byScholarOrder = (a, b) =>
    schoolRank(a.school) - schoolRank(b.school) || a.school.localeCompare(b.school) ||
    ord(TIERS, a.tier) - ord(TIERS, b.tier) || ord(RANKS, a.rank) - ord(RANKS, b.rank) || a.name.localeCompare(b.name);

  // ---------------------------------------------------------------- routing ----
  function route() {
    const h = location.hash.replace(/^#/, "") || "/";
    const [path, qs] = h.split("?");
    return { parts: path.split("/").filter(Boolean), q: new URLSearchParams(qs || "") };
  }
  function setQuery(base, obj) {
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(obj)) if (v !== "" && v != null && v !== false) q.set(k, v === true ? "1" : v);
    const s = q.toString();
    history.replaceState(null, "", "#" + base + (s ? "?" + s : ""));
  }
  function setNav(view) {
    document.querySelectorAll("#nav a").forEach((a) => a.classList.toggle("active", a.dataset.view === view));
  }

  function render() {
    const { parts, q } = route();
    const v = parts[0] || "";
    if (v === "s" && parts[1]) { setNav("scholars"); renderProfile(decodeURIComponent(parts[1])); }
    else if (v === "papers") { setNav("papers"); renderPapers(q); }
    else if (v === "schools") { setNav("schools"); renderSchools(); }
    else if (v === "about") { setNav("about"); renderAbout(); }
    else { setNav("scholars"); renderScholars(q); }
  }
  window.addEventListener("hashchange", () => { render(); });

  // ------------------------------------------------------- scholar directory ----
  const S = { q: "", school: "", rank: "", tier: "", appt: "", subs: new Set(), econOnly: false, group: true };

  function scholarMatches(s, ignore) {
    if (ignore !== "school" && S.school && s.school !== S.school) return false;
    if (ignore !== "rank" && S.rank && s.rank !== S.rank) return false;
    if (ignore !== "tier" && S.tier && s.tier !== S.tier) return false;
    if (ignore !== "appt" && S.appt && s.appt !== S.appt) return false;
    if (S.econOnly && s.appt === "外系挂靠") return false;
    if (ignore !== "subs" && S.subs.size) for (const f of S.subs) if (!s.subfields.includes(f)) return false;
    if (S.q) {
      const hay = [s.name, s.name_zh, s.school, schoolZh(s.school), schoolShort(s.school), s.title, s.fields_stated, s.evidence,
        s.subfields.join(" "), s.ba && s.ba.school, s.phd && s.phd.school, ...(s.ma || []).map((m) => m.school), s.advisors]
        .join(" ").toLowerCase();
      if (!hay.includes(S.q.toLowerCase())) return false;
    }
    return true;
  }

  function opt(value, label, sel) { return `<option value="${esc(value)}" ${sel === value ? "selected" : ""}>${esc(label)}</option>`; }

  function renderScholars(q) {
    S.q = q.get("q") || ""; S.school = q.get("school") || ""; S.rank = q.get("rank") || "";
    S.tier = q.get("tier") || ""; S.appt = q.get("appt") || ""; S.econOnly = q.get("econ") === "1";
    S.group = q.get("flat") !== "1";
    S.subs = new Set((q.get("sub") || "").split(",").filter(Boolean));

    const all = D.scholars;
    const list = all.filter((s) => scholarMatches(s)).sort(byScholarOrder);
    const cnt = (key, val, ign) => all.filter((s) => s[key] === val && scholarMatches(s, ign)).length;
    const nSchools = new Set(list.map((s) => s.school)).size;
    const nPapers = list.reduce((a, s) => a + s.n_papers, 0);
    const byRank = (r) => list.filter((s) => s.rank === r).length;
    const byTier = (t) => list.filter((s) => s.tier === t).length;

    const subCounts = {};
    for (const s of all) if (scholarMatches(s, "subs")) for (const f of s.subfields) subCounts[f] = (subCounts[f] || 0) + 1;

    const schoolsSorted = [...D.schools].filter((s) => s.n).sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name));

    app.innerHTML = `
      <p class="intro">收录美国 US News 2025 经济学排名前 30（含并列共 31 所）院校<b>经济系</b>中研究能源、环境与资源经济学（EEE）的助理教授、副教授和正教授，整理其研究方向、教育背景与职业经历，并持续补充论文与摘要。点击卡片查看详情。</p>
      <section class="stats">
        <div class="stat"><div class="n">${list.length}</div><div class="l">位学者${list.length !== all.length ? `（共 ${all.length}）` : ""}</div>
          <div class="sub">正教授 ${byRank("正教授")} · 副教授 ${byRank("副教授")} · 助理教授 ${byRank("助理教授")}</div></div>
        <div class="stat"><div class="n">${nSchools}</div><div class="l">所院校</div><div class="sub">共筛查 ${D.schools.length} 所</div></div>
        <div class="stat"><div class="n">${byTier("核心领域")}</div><div class="l">EEE 为核心领域</div>
          <div class="sub">领域之一 ${byTier("领域之一")} · 相关研究 ${byTier("相关研究")}</div></div>
        <div class="stat"><div class="n">${nPapers}</div><div class="l">篇论文已收录</div><div class="sub">持续更新中</div></div>
      </section>
      <section class="controls">
        <div class="row">
          <input id="f-q" type="search" placeholder="搜索姓名 / 院校 / 毕业学校 / 研究关键词 …" value="${esc(S.q)}" autocomplete="off">
          <select id="f-school"><option value="">全部院校</option>${schoolsSorted.map((s) =>
            opt(s.name, `#${s.rank} ${s.zh}（${s.short}） ${cnt("school", s.name, "school")}`, S.school)).join("")}</select>
          <select id="f-rank"><option value="">全部职称</option>${RANKS.map((r) => opt(r, `${r} (${cnt("rank", r, "rank")})`, S.rank)).join("")}</select>
          <select id="f-tier"><option value="">全部层级</option>${TIERS.map((t) => opt(t, `${t} (${cnt("tier", t, "tier")})`, S.tier)).join("")}</select>
          <select id="f-appt"><option value="">全部聘任类型</option>${APPTS.map((t) => opt(t, `${t} (${cnt("appt", t, "appt")})`, S.appt)).join("")}</select>
        </div>
        <div class="row">
          <span class="lbl">研究方向</span>
          ${D.subfields.filter((f) => subCounts[f] || S.subs.has(f)).map((f) =>
            `<button type="button" class="chip ${S.subs.has(f) ? "active" : ""}" data-sub="${esc(f)}">${esc(f)}<span class="c">${subCounts[f] || 0}</span></button>`).join("")}
        </div>
        <div class="row">
          <label class="toggle"><input type="checkbox" id="f-econ" ${S.econOnly ? "checked" : ""}> 排除外系挂靠</label>
          <label class="toggle"><input type="checkbox" id="f-group" ${S.group ? "checked" : ""}> 按院校分组</label>
          <button type="button" class="btn" id="f-reset">清除筛选</button>
        </div>
      </section>
      <p class="count">${list.length === all.length ? `共 ${all.length} 位学者` : `筛选出 ${list.length} / ${all.length} 位学者`}</p>
      <section id="cards"></section>`;

    const box = document.getElementById("cards");
    if (!list.length) box.innerHTML = `<p class="empty">没有符合条件的学者。</p>`;
    else if (S.group) {
      const groups = new Map();
      for (const s of list) { if (!groups.has(s.school)) groups.set(s.school, []); groups.get(s.school).push(s); }
      box.innerHTML = [...groups].map(([sch, xs]) => {
        const m = SCHOOL.get(sch) || {};
        return `<div class="group-h"><span class="rk">#${m.rank ?? ""}</span><span class="nm">${esc(m.zh || sch)}</span><span class="zh">${esc(sch)}</span><span class="n">${xs.length} 人</span></div>
          <div class="cards">${xs.map(card).join("")}</div>`;
      }).join("");
    } else box.innerHTML = `<div class="cards">${list.map(card).join("")}</div>`;

    // events
    const push = () => setQuery("/", { q: S.q, school: S.school, rank: S.rank, tier: S.tier, appt: S.appt,
      sub: [...S.subs].join(","), econ: S.econOnly, flat: !S.group });
    const rerender = () => { push(); renderScholars(route().q); };
    let t;
    const qi = document.getElementById("f-q");
    qi.addEventListener("input", () => { clearTimeout(t); t = setTimeout(() => { S.q = qi.value.trim(); push(); const pos = qi.selectionStart; renderScholars(route().q); const n = document.getElementById("f-q"); n.focus(); n.setSelectionRange(pos, pos); }, 150); });
    document.getElementById("f-school").onchange = (e) => { S.school = e.target.value; rerender(); };
    document.getElementById("f-rank").onchange = (e) => { S.rank = e.target.value; rerender(); };
    document.getElementById("f-tier").onchange = (e) => { S.tier = e.target.value; rerender(); };
    document.getElementById("f-appt").onchange = (e) => { S.appt = e.target.value; rerender(); };
    document.getElementById("f-econ").onchange = (e) => { S.econOnly = e.target.checked; rerender(); };
    document.getElementById("f-group").onchange = (e) => { S.group = e.target.checked; rerender(); };
    document.getElementById("f-reset").onclick = () => { history.replaceState(null, "", "#/"); renderScholars(new URLSearchParams()); };
    app.querySelectorAll("[data-sub]").forEach((b) => b.onclick = () => {
      const f = b.dataset.sub; S.subs.has(f) ? S.subs.delete(f) : S.subs.add(f); rerender();
    });
  }

  function card(s) {
    const phd = s.phd ? `PhD ${esc(shortSchool(s.phd.school))}${s.phd.year ? " " + s.phd.year : ""}` : "";
    return `<a class="card" href="#/s/${encodeURIComponent(s.id)}">
      <div class="top"><div class="nm">${esc(s.name)}${s.name_zh ? `<span class="zh">${esc(s.name_zh)}</span>` : ""}</div>
        <span class="badge tier-${esc(s.tier)}" title="${esc(TIER_HELP[s.tier] || "")}">${esc(s.tier)}</span></div>
      <div class="meta">${esc(s.rank)} · ${esc(schoolShort(s.school))}${s.appt && s.appt !== "经济系" ? ` · ${esc(s.appt)}` : ""}</div>
      <div>${s.subfields.map((f) => `<span class="tag">${esc(f)}</span>`).join("")}</div>
      <div class="edu"><span>${phd}</span><span class="pc ${s.n_papers ? "" : "zero"}">${s.n_papers ? s.n_papers + " 篇论文" : "论文待更新"}</span></div>
    </a>`;
  }

  const SHORT = {
    "Massachusetts Institute of Technology": "MIT", "University of California, Berkeley": "UC Berkeley",
    "University of California, Los Angeles": "UCLA", "University of California, San Diego": "UCSD",
    "London School of Economics": "LSE", "California Institute of Technology": "Caltech",
  };
  function shortSchool(n) { return SHORT[n] || n.replace(/^University of /, "U. of ").replace(/ University$/, ""); }

  // ---------------------------------------------------------------- profile ----
  function renderProfile(id) {
    const s = SCHOLAR.get(id);
    requestAnimationFrame(() => window.scrollTo(0, 0));
    if (!s) { app.innerHTML = `<p class="crumb"><a href="#/">← 返回学者列表</a></p><p class="empty">未找到该学者。</p>`; return; }
    const m = SCHOOL.get(s.school) || {};
    const papers = D.papers.filter((p) => p.scholar === id).sort(paperSort("year"));
    const edu = [];
    if (s.phd) edu.push(["博士", s.phd]);
    for (const x of s.ma || []) edu.push(["硕士", x]);
    if (s.ba) edu.push(["本科", s.ba]);
    const links = [link(s.homepage, "个人主页 ↗"), link(s.cv, "CV ↗"), link(s.profile, "院系页面 ↗")].filter(Boolean).join("");
    const kv = (k, v) => v ? `<dt>${k}</dt><dd>${v}</dd>` : "";

    app.innerHTML = `
      <p class="crumb"><a href="#/">学者</a> / <a href="#/?school=${encodeURIComponent(s.school)}">${esc(m.zh || s.school)}</a> / ${esc(s.name)}</p>
      <section class="profile-h">
        <h1>${esc(s.name)}${s.name_zh ? `<span class="zh">${esc(s.name_zh)}</span>` : ""}</h1>
        <div class="ttl">${esc(s.title || s.rank)} · ${esc(s.school)}${m.zh ? `（${esc(m.zh)}）` : ""}</div>
        <div>
          <span class="badge tier-${esc(s.tier)}" title="${esc(TIER_HELP[s.tier] || "")}">EEE ${esc(s.tier)}</span>
          <span class="badge plain">${esc(s.rank)}</span>
          <span class="badge plain">${esc(s.appt === "外系挂靠" ? "外系挂靠（经济系列为 affiliated）" : s.appt)}</span>
          ${s.flags.map((f) => `<span class="badge plain">${esc(f)}</span>`).join("")}
        </div>
        <div style="margin-top:10px">${s.subfields.map((f) => `<a class="tag" href="#/?sub=${encodeURIComponent(f)}">${esc(f)}</a>`).join("")}</div>
        ${links ? `<div class="links">${links}</div>` : ""}
      </section>

      <div class="grid2">
        <div>
          <section class="box"><h3>教育背景</h3>
            ${edu.length ? `<ul class="timeline">${edu.map(([d, x]) =>
              `<li><span class="deg">${d}</span><span class="yr">${x.year || "年份不详"}</span><span class="fd">${esc(x.school)}${x.field ? " · " + esc(x.field) : ""}</span></li>`).join("")}</ul>`
              : `<p class="small">暂无</p>`}
            ${s.advisors ? `<p class="small" style="margin-top:6px">博士导师 / 委员会：${esc(s.advisors)}</p>` : ""}
          </section>
          <section class="box"><h3>职业经历</h3>
            <dl class="kv">
              ${kv("现任", esc(s.title || s.rank))}
              ${kv("现职称起始", esc(s.rank_since))}
              ${kv("入职现单位", esc(s.joined))}
              ${kv("首份工作", esc(s.first_job))}
            </dl>
            ${s.career.length ? `<ul class="career" style="margin-top:10px">${s.career.map((c) => `<li>${esc(c)}</li>`).join("")}</ul>` : ""}
          </section>
          <section class="box"><h3>学术兼职 / 研究机构</h3><p>${esc(s.affiliations) || `<span class="small">暂无</span>`}</p></section>
        </div>
        <div>
          <section class="box"><h3>论文与摘要 <span class="small">（${papers.length} 篇）</span></h3>
            ${papers.length ? papers.map((p) => paperHtml(p, false)).join("") : `
              <div class="placeholder">该学者的论文与摘要正在整理中。<br>
                <a class="btn primary" href="${editUrl(id)}" target="_blank" rel="noopener">在 GitHub 上添加论文</a></div>`}
            ${papers.length ? `<p class="small"><a href="${editUrl(id)}" target="_blank" rel="noopener">＋ 补充 / 修改论文</a></p>` : ""}
          </section>
          <section class="box"><h3>研究方向</h3>
            ${s.fields_stated ? `<p><span class="small">自述领域：</span>${esc(s.fields_stated)}</p>` : ""}
            ${s.evidence ? `<p><span class="small">EEE 相关研究线索：</span>${esc(s.evidence)}</p>` : ""}
          </section>
          <section class="box"><h3>数据说明</h3>
            <p class="small">${s.notes ? esc(s.notes) + "<br>" : ""}${s.cv_date ? "CV 日期：" + esc(s.cv_date) + " · " : ""}信息核对：${esc(s.checked || "—")} ·
              <a href="${editUrl(id)}" target="_blank" rel="noopener">纠错 / 编辑此页</a></p>
          </section>
        </div>
      </div>`;
  }

  // ----------------------------------------------------------------- papers ----
  const P = { q: "", sub: "", status: "", sort: "added" };
  const paperSort = (key) => (a, b) => key === "added"
    ? (b.added || "").localeCompare(a.added || "") || (b.year || 0) - (a.year || 0)
    : (b.year || 0) - (a.year || 0) || (b.added || "").localeCompare(a.added || "");

  function paperHtml(p, showScholar) {
    const sc = SCHOLAR.get(p.scholar);
    const title = p.url ? `<a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a>` : esc(p.title);
    const meta = [p.authors.length ? esc(p.authors.join(", ")) : "", p.venue ? `<span class="venue">${esc(p.venue)}</span>` : "", p.year || ""]
      .filter(Boolean).join(" · ");
    return `<article class="paper">
      <div class="pt">${title}${p.status ? `<span class="badge st st-${esc(p.status)}">${esc(p.status)}</span>` : ""}</div>
      ${p.title_zh ? `<div class="ptz">${esc(p.title_zh)}</div>` : ""}
      ${meta ? `<div class="pm">${meta}</div>` : ""}
      ${showScholar && sc ? `<div class="by"><a href="#/s/${encodeURIComponent(sc.id)}">${esc(sc.name)}</a> <span class="small">· ${esc(schoolShort(sc.school))}</span></div>` : ""}
      ${p.keywords.length ? `<div style="margin-top:5px">${p.keywords.map((k) => `<span class="tag">${esc(k)}</span>`).join("")}</div>` : ""}
      ${p.abstract ? `<details><summary>摘要</summary><div class="abs">${esc(p.abstract)}</div></details>` : ""}
      ${(p.pdf || p.replication) ? `<div class="pm">${link(p.pdf, "PDF ↗")} ${link(p.replication, "代码与数据 ↗")}</div>` : ""}
    </article>`;
  }

  function renderPapers(q) {
    P.q = q.get("q") || ""; P.sub = q.get("sub") || ""; P.status = q.get("status") || ""; P.sort = q.get("sort") || "added";
    const all = D.papers;
    const list = all.filter((p) => {
      const sc = SCHOLAR.get(p.scholar) || { subfields: [], name: "" };
      if (P.sub && !sc.subfields.includes(P.sub)) return false;
      if (P.status && p.status !== P.status) return false;
      if (P.q) {
        const hay = [p.title, p.title_zh, p.abstract, p.venue, p.authors.join(" "), p.keywords.join(" "), sc.name, sc.school].join(" ").toLowerCase();
        if (!hay.includes(P.q.toLowerCase())) return false;
      }
      return true;
    }).sort(paperSort(P.sort));
    const nSch = new Set(all.map((p) => p.scholar)).size;

    app.innerHTML = `
      <p class="intro">汇总所有学者已收录的论文与摘要。论文按学者逐步补充，欢迎在 GitHub 上协助添加。</p>
      <section class="stats">
        <div class="stat"><div class="n">${all.length}</div><div class="l">篇论文</div></div>
        <div class="stat"><div class="n">${nSch}</div><div class="l">位学者已有论文</div><div class="sub">共 ${D.scholars.length} 位学者</div></div>
        <div class="stat"><div class="n">${all.filter((p) => p.abstract).length}</div><div class="l">篇含摘要</div></div>
      </section>
      <section class="controls"><div class="row">
        <input id="p-q" type="search" placeholder="搜索标题 / 摘要 / 作者 / 期刊 / 关键词 …" value="${esc(P.q)}" autocomplete="off">
        <select id="p-sub"><option value="">全部研究方向</option>${D.subfields.map((f) => opt(f, f, P.sub)).join("")}</select>
        <select id="p-status"><option value="">全部状态</option>${D.statuses.map((f) => opt(f, f, P.status)).join("")}</select>
        <select id="p-sort">${opt("added", "按收录时间（最新）", P.sort)}${opt("year", "按年份（最新）", P.sort)}</select>
      </div></section>
      <p class="count">${list.length === all.length ? `共 ${all.length} 篇` : `筛选出 ${list.length} / ${all.length} 篇`}</p>
      <section>${list.length ? list.map((p) => paperHtml(p, true)).join("") : `
        <div class="placeholder">${all.length ? "没有符合条件的论文。" : "论文库正在建设中：各学者的论文与摘要将陆续补充。"}<br>
          <a class="btn" href="#/about">查看如何添加论文</a></div>`}</section>`;

    const push = () => setQuery("/papers", { q: P.q, sub: P.sub, status: P.status, sort: P.sort === "added" ? "" : P.sort });
    const rer = () => { push(); renderPapers(route().q); };
    let t;
    const qi = document.getElementById("p-q");
    qi.addEventListener("input", () => { clearTimeout(t); t = setTimeout(() => { P.q = qi.value.trim(); push(); renderPapers(route().q); const n = document.getElementById("p-q"); n.focus(); n.setSelectionRange(n.value.length, n.value.length); }, 150); });
    document.getElementById("p-sub").onchange = (e) => { P.sub = e.target.value; rer(); };
    document.getElementById("p-status").onchange = (e) => { P.status = e.target.value; rer(); };
    document.getElementById("p-sort").onchange = (e) => { P.sort = e.target.value; rer(); };
  }

  // ---------------------------------------------------------------- schools ----
  function renderSchools() {
    const rows = [...D.schools].sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name));
    const max = Math.max(...rows.map((r) => r.n));
    const per = (name, f) => D.scholars.filter((s) => s.school === name && f(s)).length;
    const phd = {};
    for (const s of D.scholars) if (s.phd) { const k = shortSchool(s.phd.school); phd[k] = (phd[k] || 0) + 1; }
    const phdTop = Object.entries(phd).sort((a, b) => b[1] - a[1]).slice(0, 12);
    const pmax = phdTop.length ? phdTop[0][1] : 1;
    const decade = {};
    for (const s of D.scholars) if (s.phd && typeof s.phd.year === "number") { const d = Math.floor(s.phd.year / 10) * 10; decade[d] = (decade[d] || 0) + 1; }
    const dmax = Math.max(1, ...Object.values(decade));

    app.innerHTML = `
      <p class="intro">按 US News 2025 经济学研究生项目排名列出所有被筛查的院校（排名并列，故共 31 所）。点击某一行查看该校学者。</p>
      <div class="split">
        <section class="tbl-wrap"><table>
          <thead><tr><th>排名</th><th>院校</th><th class="num">EEE 学者</th><th class="num">核心领域</th><th class="num">筛查人数</th><th class="num">论文</th></tr></thead>
          <tbody>${rows.map((r) => `<tr class="${r.n ? "clk" : ""}" data-school="${esc(r.name)}">
            <td>#${r.rank}</td>
            <td><b>${esc(r.zh)}</b> <span class="small">${esc(r.name)}</span>${r.note ? `<div class="small">${esc(r.note)}</div>` : ""}</td>
            <td class="num">${r.n}<span class="bar" style="width:${r.n ? Math.max(4, 60 * r.n / max) : 0}px"></span></td>
            <td class="num">${per(r.name, (s) => s.tier === "核心领域")}</td>
            <td class="num"><a href="${esc(r.url)}" target="_blank" rel="noopener" title="院系教师名录">${r.screened}</a></td>
            <td class="num">${D.papers.filter((p) => (SCHOLAR.get(p.scholar) || {}).school === r.name).length}</td></tr>`).join("")}
          </tbody></table></section>
        <div>
          <section class="box"><h3>博士毕业院校分布（前 12）</h3>
            <table><tbody>${phdTop.map(([k, n]) => `<tr><td>${esc(k)}</td><td class="num">${n}<span class="bar" style="width:${90 * n / pmax}px"></span></td></tr>`).join("")}</tbody></table></section>
          <section class="box"><h3>博士毕业年代</h3>
            <table><tbody>${Object.keys(decade).sort().map((d) => `<tr><td>${d}s</td><td class="num">${decade[d]}<span class="bar" style="width:${90 * decade[d] / dmax}px"></span></td></tr>`).join("")}</tbody></table></section>
        </div>
      </div>`;
    app.querySelectorAll("tr.clk").forEach((tr) => tr.onclick = (e) => {
      if (e.target.closest("a")) return;
      location.hash = "#/?school=" + encodeURIComponent(tr.dataset.school);
    });
  }

  // ------------------------------------------------------------------ about ----
  function renderAbout() {
    app.innerHTML = `<article class="prose">
      <h2>这是什么</h2>
      <p>本站整理美国顶尖经济系中研究<b>能源、环境与资源经济学</b>（Energy, Environmental &amp; Resource Economics, EEE）的教授，包括研究方向、本科/硕士/博士教育背景、职业经历，并逐步补充其论文与摘要，方便同学了解领域学者、选择申请方向、寻找合作者。</p>

      <h2>收录范围</h2>
      <ul>
        <li><b>院校</b>：US News 2025 经济学研究生项目排名前 30，因并列共 31 所。</li>
        <li><b>院系</b>：仅限<b>经济系</b>教师名录。农业与资源经济系（ARE）、公共政策学院、环境学院、商学院等的学者，只有在经济系页面被列为 faculty / affiliated faculty 时才收录，并标注为「外系挂靠」。因此 Kenneth Gillingham（Yale 环境学院）、Wolfram Schlenker（Columbia SIPA）等知名学者暂未收录。</li>
        <li><b>职称</b>：在编（tenure-line）的助理教授、副教授、正教授；不含讲师、教学型教职、访问学者、博士后和荣休教授。</li>
      </ul>

      <h2>领域层级</h2>
      <ul>
        <li><span class="badge tier-核心领域">核心领域</span> EEE 是其主要研究领域。</li>
        <li><span class="badge tier-领域之一">领域之一</span> 在院系页面或简历中将 EEE 列为研究领域之一。</li>
        <li><span class="badge tier-相关研究">相关研究</span> 未明确列为领域，但有较多 EEE 相关论文（如气候宏观、电力市场 IO 等），判断有一定主观性。</li>
      </ul>
      <p>标记「农业为主」表示其 EEE 相关研究主要是发展经济学中的农业议题；「EEE研究较早」表示相关研究多为早年工作。</p>

      <h2>数据来源</h2>
      <p>院系教师名录、个人主页与公开 CV（2026 年 10 月整理），部分博士导师信息来自论文记录、RePEc Genealogy 等，具体见各学者页面的「数据说明」。难免有错漏，欢迎纠正。</p>

      <h2>如何添加论文与摘要</h2>
      <p>每位学者对应仓库中的一个文件 <code>data/scholars/姓名.md</code>。在学者页面点击「在 GitHub 上添加论文」即可直接在网页上编辑，在文件末尾按以下格式添加（每篇以 <code>###</code> 开头）：</p>
<pre>### Why Is U.S. Manufacturing Air Quality Improving?
- 中文标题：美国制造业空气质量为何改善？
- 作者：Joseph S. Shapiro; Reed Walker
- 年份：2018
- 发表：American Economic Review
- 状态：已发表
- 链接：https://doi.org/...
- 关键词：空气污染; 环境规制
- 收录日期：2026-10-10

摘要：在这里粘贴摘要，可以是英文或中文，可以多段。</pre>
      <p>状态可选：已发表 / 即将发表 / 修改重投 / 工作论文。提交后网站约 1–2 分钟自动更新。没有编辑权限的话，也可以在 GitHub 上提交 Issue。</p>

      <h2>修改学者信息</h2>
      <p>同一文件开头 <code>---</code> 之间是学者信息（职称、学历、经历等），按「字段: 值」格式修改即可。新增学者可复制 <code>data/scholars/_TEMPLATE.md</code>。</p>
    </article>`;
  }

  render();
})();
